#!/usr/bin/env bash
# recipes/crate-proc-macro2--1-0-78/build.sh -- stage the proc-macro2 1.0.78 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/proc-macro2-1.0.78"
